SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2008.YEAR, Станции2008.NUST, Станции2008.nr, Станции2008.E, Станции2008.EOTP, Станции2008.EURT, Станции2008.EUST, Станции2008.Q, Станции2008.TURT, Станции2008.TUST, Станции2008.B, Станции2008.GAZ, Доп_угли2008.gazpp, Станции2008.MAZUT, Станции2008.TORF, Станции2008.SLAN, Станции2008.GTT AS Выражение1, Станции2008.PROCH, Станции2008.UGOL, Станции2008.DON, Станции2008.PODM, Станции2008.PECH, Доп_угли2008.int, Доп_угли2008.vork, Станции2008.ARKT, Станции2008.KUZN, Станции2008.URAL, Доп_угли2008.sver, Доп_угли2008.chel, Доп_угли2008.kizel, Станции2008.BASHK, Станции2008.EKIB, Станции2008.KARAG, Станции2008.KAN, Доп_угли2008.nazar, Доп_угли2008.ibor, Доп_угли2008.berez, Доп_угли2008.per, Станции2008.IRKUT, Доп_угли2008.azey, Доп_угли2008.mug, Доп_угли2008.cher, Доп_угли2008.jer, Станции2008.HAK, Станции2008.TUV, Станции2008.BUR, Доп_угли2008.gusin, Доп_угли2008.tugn, Станции2008.CHIT, Доп_угли2008.har, Доп_угли2008.urt, Станции2008.NER AS Выражение2, Доп_угли2008.neru, Доп_угли2008.pyak, Станции2008.RAICH AS Выражение3, Доп_угли2008.rai, Доп_угли2008.erk, Станции2008.URG, Станции2008.PRIM, Станции2008.LUCH, Станции2008.MAG, Станции2008.SAH, Станции2008.USHUM, Станции2008.QOTR, Станции2008.SNK, Станции2008.EWTP, Станции2008.NT, Станции2008.OBOR, Станции2008.VED, Станции2008.OBL, Станции2008.DEP, Станции2008.OES, Станции2008.ER, Станции2008.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Станции2008.NTsum, Станции2008.GK, Станции2008.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM ((((((Станции2008 INNER JOIN Имена_станций ON Станции2008.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2008.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2008.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2008 ON (Станции2008.NUMB1120=Доп_угли2008.NUMB1120) AND (Станции2008.YEAR=Доп_угли2008.YEAR)) LEFT JOIN имена_ГК ON Станции2008.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2008.BE=имена_БЕ.code) LEFT JOIN Города ON Имена_станций.codegor=Города.code;
